% Math macros for the CaoZhu blueprint — consolidated for hgraph/KaTeX.

% --- from macros/early.tex ---
% Macros used by the Cao--Zhu source through line 9837.
\providecommand{\Ric}{\operatorname{Ric}}
\providecommand{\Vol}{\operatorname{Vol}}
\providecommand{\inj}{\operatorname{inj}}
\providecommand{\tr}{\operatorname{tr}}
\providecommand{\be}{\begin{equation}}
\providecommand{\ee}{\end{equation}}
\providecommand{\nn}{\nonumber}
\providecommand{\index}[1]{}
\providecommand{\endproof}{\hfill$\square$\medskip}
\providecommand{\proves}[1]{}
\providecommand{\sketch}{\noindent\emph{Sketch.}\ }
\providecommand{\sp}[1]{^{#1}}
\providecommand{\texorpdfstring}[2]{#1}

% --- from macros/common.tex ---
\newtheorem{theorem}{Theorem}[chapter]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}

\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}

\providecommand{\Rm}{\operatorname{Rm}}
\providecommand{\Hess}{\operatorname{Hess}}
\providecommand{\dd}{\,\mathrm{d}}
\providecommand{\bysame}{\leavevmode\hbox to 3em{\hrulefill}\thinspace}

% Horizon provenance metadata is parsed into the DAG and hidden in print.
\providecommand{\dcref}[1]{}
\providecommand{\group}[1]{}
\providecommand{\source}[1]{}
\providecommand{\home}[1]{}
\providecommand{\github}[1]{}
\providecommand{\dochome}[1]{}
\providecommand{\uses}[1]{}
